const { withDangerousMod } = require('expo/config-plugins');
const fs = require('node:fs');
const path = require('node:path');

/**
 * Copies the ring tone into `android/app/src/main/res/raw/`.
 *
 * A notification channel names its sound by bare filename — `offer_ring` — and Android only
 * resolves that from `res/raw`. Nothing in Expo's managed config puts an arbitrary audio file
 * there, and `android/` is regenerated by every prebuild, so hand-copying it once would silently
 * vanish on the next one and the channel would fall back to the default notification sound.
 *
 * Android resource names must be lowercase letters, digits and underscores — no dashes, no
 * uppercase — which is why the asset is `offer_ring.mp3` and not `offer-ring.mp3`.
 */
module.exports = function withOfferSound(config) {
  return withDangerousMod(config, [
    'android',
    async (cfg) => {
      const source = path.join(cfg.modRequest.projectRoot, 'assets', 'offer_ring.mp3');
      const rawDir = path.join(
        cfg.modRequest.platformProjectRoot,
        'app',
        'src',
        'main',
        'res',
        'raw',
      );

      if (!fs.existsSync(source)) {
        throw new Error(
          `withOfferSound: ${source} is missing. The offer channel names this file as its sound; ` +
            'without it every trip offer falls back to the default notification tone.',
        );
      }

      fs.mkdirSync(rawDir, { recursive: true });
      fs.copyFileSync(source, path.join(rawDir, 'offer_ring.mp3'));
      return cfg;
    },
  ]);
};
